import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline
cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor conv2d_cute_forward(torch::Tensor x,
                                   torch::Tensor w,
                                   c10::optional<torch::Tensor> b,
                                   int stride, int padding);
"""
cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
using namespace cute;
constexpr int Threads    = 256;
constexpr int OcPerBlock = 16;
constexpr int TileOH     = 16;
constexpr int TileOW     = 16;
static_assert(TileOH * TileOW == Threads, "TileOH*TileOW must equal Threads");
template <typename T>
__global__ void conv2d_cute_kernel(
    const T* __restrict__ X,
    const T* __restrict__ Wt,
    const T* __restrict__ Bias,
    T* __restrict__ Y,
    int N, int Cin, int H, int Win,
    int Cout, int K, int stride, int padding,
    int Hout, int Wout, int ow_tiles)
{
  extern __shared__ unsigned char smem_raw[];
  const int KK = Cin * K * K;
  const int SH = (TileOH - 1) * stride + K;
  const int SW = (TileOW - 1) * stride + K;
  T* sW_ptr = reinterpret_cast<T*>(smem_raw);
  T* sX_ptr = sW_ptr + (size_t)OcPerBlock * (size_t)KK;
  const int tid = threadIdx.x;
  const int n       = blockIdx.z;
  const int oc_tile = blockIdx.y;
  const int oc_base = oc_tile * OcPerBlock;
  const int tile_idx    = blockIdx.x;
  const int ow_tile_idx = tile_idx % ow_tiles;
  const int oh_tile_idx = tile_idx / ow_tiles;
  const int oh_base = oh_tile_idx * TileOH;
  const int ow_base = ow_tile_idx * TileOW;
  const int r = tid / TileOW;
  const int c = tid - r * TileOW;
  const int oh = oh_base + r;
  const int ow = ow_base + c;
  const bool valid_out = (oh < Hout) && (ow < Wout);
  const int64_t sXn = (int64_t)Cin * H * Win;
  const int64_t sXc = (int64_t)H * Win;
  const int64_t sXh = (int64_t)Win;
  const int64_t sYn = (int64_t)Cout * Hout * Wout;
  const int64_t sYc = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;
  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(Cin, H, Win),
      make_stride(sXc, sXh, Int<1>{})
  );
  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(Cout, Hout, Wout),
      make_stride(sYc, sYh, Int<1>{})
  );
  // Weight flattened as (Cout, Cin*K*K)
  auto mW = make_tensor(
      make_gmem_ptr(Wt),
      make_shape(Cout, KK),
      make_stride(KK, Int<1>{})
  );
  auto sW = make_tensor(
      make_smem_ptr(sW_ptr),
      make_shape(Int<OcPerBlock>{}, KK),
      make_stride(KK, Int<1>{})
  );
  // Load weight tile for this oc-block into shared memory (reused across all cin/kh/kw iterations)
  int total_w = OcPerBlock * KK;
  for (int idx = tid; idx < total_w; idx += Threads) {
    int oc_local = idx / KK;
    int kk       = idx - oc_local * KK;
    int oc       = oc_base + oc_local;
    T val = T(0);
    if (oc < Cout) {
      val = mW(oc, kk);
    }
    sW(oc_local, kk) = val;
  }
  __syncthreads();
  float acc[OcPerBlock];
  #pragma unroll
  for (int oc_local = 0; oc_local < OcPerBlock; ++oc_local) {
    int oc = oc_base + oc_local;
    float bval = 0.0f;
    if (Bias != nullptr && oc < Cout) {
      bval = (float)Bias[oc];
    }
    acc[oc_local] = bval;
  }
  // Cooperative shared-memory staging of the input tile: for each input channel, the
  // whole CTA loads the (overlapping) input footprint needed by its output tile into a
  // single reused buffer, and every thread consumes it for all K*K taps and all
  // OcPerBlock output channels, before moving on to the next input channel. This keeps
  // the input staging buffer bounded to one channel's footprint (SH*SW), instead of
  // requiring Cin*SH*SW shared memory for the whole channel range at once.
  const int SHW = SH * SW;
  for (int cin = 0; cin < Cin; ++cin) {
    for (int idx = tid; idx < SHW; idx += Threads) {
      int lr = idx / SW;
      int lc = idx - lr * SW;
      int ih = oh_base * stride - padding + lr;
      int iw = ow_base * stride - padding + lc;
      T val = T(0);
      if ((unsigned)ih < (unsigned)H && (unsigned)iw < (unsigned)Win) {
        val = mX(cin, ih, iw);
      }
      sX_ptr[idx] = val;
    }
    __syncthreads();
    if (valid_out) {
      for (int kh = 0; kh < K; ++kh) {
        int sx_row = r * stride + kh;
        const T* row_ptr = sX_ptr + (size_t)sx_row * SW;
        for (int kw = 0; kw < K; ++kw) {
          int sx_col = c * stride + kw;
          float xval = (float)row_ptr[sx_col];
          int kk = (cin * K + kh) * K + kw;
          #pragma unroll
          for (int oc_local = 0; oc_local < OcPerBlock; ++oc_local) {
            float wval = (float)sW(oc_local, kk);
            acc[oc_local] += xval * wval;
          }
        }
      }
    }
    __syncthreads();
  }
  if (valid_out) {
    #pragma unroll
    for (int oc_local = 0; oc_local < OcPerBlock; ++oc_local) {
      int oc = oc_base + oc_local;
      if (oc >= Cout) continue;
      mY(oc, oh, ow) = static_cast<T>(acc[oc_local]);
    }
  }
}
torch::Tensor conv2d_cute_forward(torch::Tensor x,
                                   torch::Tensor w,
                                   c10::optional<torch::Tensor> b,
                                   int stride, int padding) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");
  TORCH_CHECK(x.dim() == 4, "x must be [N, C, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [Cout, Cin, K, K]");
  int64_t N   = x.size(0);
  int64_t Cin = x.size(1);
  int64_t H   = x.size(2);
  int64_t Win = x.size(3);
  int64_t Cout = w.size(0);
  TORCH_CHECK(w.size(1) == Cin, "w.size(1) must equal Cin");
  int64_t K = w.size(2);
  TORCH_CHECK(w.size(3) == K, "kernel must be square for this kernel implementation");
  TORCH_CHECK(stride > 0, "stride must be > 0");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");
  int64_t Hout = (H + 2 * padding - K) / stride + 1;
  int64_t Wout = (Win + 2 * padding - K) / stride + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "Invalid output size computed");
  auto x_c = x.contiguous();
  auto w_c = w.contiguous();
  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }
  auto y = torch::empty({N, Cout, Hout, Wout}, x.options());
  int64_t oh_tiles = (Hout + TileOH - 1) / TileOH;
  int64_t ow_tiles = (Wout + TileOW - 1) / TileOW;
  dim3 block(Threads);
  dim3 grid(
      (unsigned)(oh_tiles * ow_tiles),
      (unsigned)((Cout + OcPerBlock - 1) / OcPerBlock),
      (unsigned)N
  );
  int64_t KK = Cin * K * K;
  int64_t SH = (TileOH - 1) * stride + K;
  int64_t SW = (TileOW - 1) * stride + K;
  size_t smem_bytes = (size_t)(OcPerBlock * KK + SH * SW) * sizeof(float);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  if (smem_bytes > 48 * 1024) {
    cudaFuncSetAttribute(conv2d_cute_kernel<float>,
                          cudaFuncAttributeMaxDynamicSharedMemorySize,
                          (int)smem_bytes);
  }
  conv2d_cute_kernel<float><<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)Cin, (int)H, (int)Win,
      (int)Cout, (int)K, (int)stride, (int)padding,
      (int)Hout, (int)Wout, (int)ow_tiles
  );
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_cute_kernel launch failed: ", cudaGetErrorString(err));
  return y;
}
"""
conv2d_ext = load_inline(
    name="cute_conv2d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv2d_cute_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)
class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        in_channels = 3
        out_channels = 96
        kernel_size = 11
        self.stride = 4
        self.padding = 2
        self.weight = nn.Parameter(torch.empty(out_channels, in_channels, kernel_size, kernel_size))
        self.bias = nn.Parameter(torch.empty(out_channels))
        self.reset_parameters()
        self._ext = conv2d_ext
    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        fan_in = self.weight.size(1) * self.weight.size(2) * self.weight.size(3)
        bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
        init.uniform_(self.bias, -bound, bound)
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv2d_cute_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias,
            int(self.stride),
            int(self.padding),
        )

