  int ow_arr[PVec];

  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int p = p_block + tid + i * Threads;
    p_idx[i] = p;
    if (p < P_total) {
      oh_arr[i] = p / Wout;
      ow_arr[i] = p - oh_arr[i] * Wout;
    } else {
      oh_arr[i] = 0;
      ow_arr[i] = 0;
    }
  }

  float acc[OcPerBlock][PVec];
  #pragma unroll
  for (int oc_local = 0; oc_local < OcPerBlock; ++oc_local) {
    int oc = oc_base + oc_local;
    float bval = 0.0f;
    if (Bias != nullptr && oc < Cout) {
      bval = (float)Bias[oc];
    }
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      acc[oc_local][i] = bval;
    }
  }

  for (int cin = 0; cin < Cin; ++cin) {
    for (int kh = 0; kh < K; ++kh) {
      #pragma unroll
      for (int i = 0; i < PVec; ++i) {
        int p = p_idx[i];
        if (p >= P_total) continue;

        int ih = oh_arr[i] * stride - padding + kh;
        if ((unsigned)ih >= (unsigned)H) continue;

        for (int kw = 0; kw < K; ++kw) {
          int iw = ow_arr[i] * stride - padding + kw;
          if ((unsigned)iw >= (unsigned)Win) continue;

          float xval = (float)mX(cin, ih, iw);
          int kk = (cin * K + kh) * K + kw;

          #pragma unroll
          for (int oc_local = 0; oc_local < OcPerBlock; ++oc_local) {
            float wval = (float)sW(oc_local, kk);
            acc[oc_local][i] += xval * wval;
          }
        }
      }
    }
  }

  #pragma unroll
  for (int oc_local = 0; oc_local < OcPerBlock; ++oc_local) {
    int oc = oc_base + oc_local;
    if (oc >= Cout) continue;
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      int p = p_idx[i];
      if (p >= P_total) continue;
      mY(oc, oh_arr[i], ow_arr[i]) = static_cast<T>(acc[oc_local][i]);
    }
  }
}

torch::Tensor conv2d_cute_forward(torch::Tensor x,
                                   torch::Tensor w,
                                   c10::optional<torch::Tensor> b,
                                   int stride, int padding) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");

  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");

  TORCH_CHECK(x.dim() == 4, "x must be [N, C, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [Cout, Cin, K, K]");

  int64_t N   = x.size(0);
  int64_t Cin = x.size(1);
  int64_t H   = x.size(2);
  int64_t Win = x.size(3);

  int64_t Cout = w.size(0);
  TORCH_CHECK(w.size(1) == Cin, "w.size(1) must equal Cin");
  int64_t K = w.size(2);
  TORCH_CHECK(w.size(3) == K, "kernel must be square for this kernel implementation");

  TORCH_CHECK(stride > 0, "stride must be > 0");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");

  int64_t Hout = (H + 2 * padding - K) / stride + 1;
  int64_t Wout = (Win + 2 * padding - K) / stride + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "Invalid output size computed");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, Cout, Hout, Wout}, x.options());

  const int64_t P_total = Hout * Wout;
  const int64_t PTile   = Threads * PVec;

  dim3 block(Threads);
  dim3 grid(
      (unsigned)((P_total + PTile - 1) / PTile),
      (unsigned)((Cout + OcPerBlock - 1) / OcPerBlock),
      (unsigned)N
  );

  int64_t KK = Cin * K * K;
  size_t smem_bytes = (size_t)OcPerBlock * (size_t)KK * sizeof(float);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  if (smem_bytes > 48 * 1024) {
    cudaFuncSetAttribute(conv2d_cute_kernel<float>,
                          cudaFuncAttributeMaxDynamicSharedMemorySize,
                          (int)smem_bytes);
  }

  conv2d_cute_kernel<float><<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)Cin, (int)H, (int)Win,
      (int)Cout, (int)K, (int)stride, (int)padding,
      (int)Hout, (int)Wout
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_cute_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
